mapper.select:
SELECT greenhouse_id AS greenhouseId, member_id AS memberId, greenhouse_name AS greenhouseName, greenhouse_type AS greenhouseType, cover_type AS coverType, building_count AS buildingCount, side_height AS sideHeight, width, length, registered_area AS registeredArea, medium_type AS mediumType, greenhouse_image_url AS greenhouseImageUrl, created_at AS createdAt, updated_at AS updatedAt FROM greenhouse WHERE member_id = #{memberId}
AND greenhouse_id = #{greenhouseId}
AND LOCATE(#{name}, greenhouse_name) > 0
AND greenhouse_type = #{type}
AND cover_type = #{cover}
AND medium_type = #{medium}
ORDER BY created_at DESC, greenhouse_id DESC

mapper.update:
UPDATE crop
SET crop_name = #{cropName},
    variety_name = #{varietyName}
WHERE crop_id = #{cropId}
